      return na - nb;
    });
    if (keys.length < 2) return null;
    var freqs = [];
    var leftArr = [];
    var rightArr = [];
    var diffArr = [];
    for (var i = 0; i < keys.length; i++) {
      var k = keys[i];
      var hz = parseInt(String(k).replace(/[^0-9]/g, ""), 10);
      if (!isNaN(hz)) {
        freqs.push(hz);
        leftArr.push(left[k] != null ? left[k] : null);
        rightArr.push(right[k] != null ? right[k] : null);
        diffArr.push(diff[k] != null ? diff[k] : null);
      }
    }
    return freqs.length >= 2 ? { freqs: freqs, left: leftArr, right: rightArr, diff: diffArr } : null;
  }

  function render_step_sweep(frm) {
    var g = safe_json(frm.doc.final_graph_json, null);
    var isSweep = g && (g.type === "sweep" || g.type === "step_sweep") && (g.freqs || []).length >= 2;
    if (!isSweep) {
      var lrd = safe_json(frm.doc.left_right_diff_summary_json, null);
      g = build_sweep_from_lrd(lrd);
    }
    if (!g || !g.freqs || g.freqs.length < 2) {
      return '<div class="pts3-result-section"><h4>Step Sweep</h4><p class="pts3-result-no-data">No sweep data</p></div>';
    }
    var freqs = g.freqs || [];
    var left = g.left || [];
    var right = g.right || [];
    var diff = g.diff || [];
    var html = '<div class="pts3-result-section"><h4>Step Sweep</h4>';
    if (freqs.length >= 2) {
      var sweepFs = pts3_axis_font();
      var sweepAxis = CHART.axisColor;
      var chartResult = render_sweep_chart_svg(freqs, left, right, diff);
      var sweepData = JSON.stringify({ freqs: freqs, left: left, right: right, diff: diff, coords: chartResult.coords });
      var diffHzSvg = render_diff_vs_hz_svg(freqs, diff);
      var sweepLegend = '<p style="font-size:' + sweepFs + 'px;margin:0 0 4px 0;"><span style="color:' + CHART.lineLeft + '">—</span> Left &nbsp; <span style="color:' + CHART.lineRight + '">—</span> Right &nbsp; <span style="color:' + CHART.lineDiff + '">- -</span> Diff</p>';
      var sweepBlock = sweepLegend + '<div class="pts3-sweep-chart-container" data-sweep="' + escape_html(sweepData) + '"><div class="pts3-sweep-tooltip" id="pts3-sweep-tooltip"></div>' + chartResult.svg + "</div>";
      if (diffHzSvg) {
        html += '<div class="pts3-sweep-diff-row">';
        html += '<div class="pts3-sweep-diff-col"><div class="pts3-chart-wrap">' + sweepBlock + "</div></div>";
        html += '<div class="pts3-sweep-diff-col"><div class="pts3-chart-wrap pts3-diff-hz-wrap"><p style="font-size:' + sweepFs + 'px;margin:0 0 4px 0;color:' + sweepAxis + ';">Diff vs frequency (Hz)</p>' + diffHzSvg + "</div></div>";
        html += "</div>";
      } else {
        html += '<div class="pts3-chart-wrap">' + sweepBlock + "</div>";
      }
    }
    var modeOrder = ["Mode1", "Mode2", "Mode3", "Mode0"];
    var mMode = safe_json(frm.doc.mode_values_json, null);

    function mode_cell_for_row(modeKey, channel) {
      if (!mMode || typeof mMode !== "object") {
        return "<td></td>";
      }
      var v = get_mode_value(mMode, modeKey);
      if (!v || typeof v !== "object") {
        return "<td></td>";
      }
      var num = channel === "left" ? v.p1 : channel === "right" ? v.p2 : v.diff;
      if (num == null) {
        return "<td></td>";
      }
      if (channel === "diff") {
        return pts3_diff_td_open(num) + escape_html(format_num(num)) + "</td>";
      }
      return "<td>" + escape_html(format_num(num)) + "</td>";
    }

    html += '<div class="pts3-sweep-table-scroll"><table class="pts3-result-table pts3-sweep-mode-unified"><thead><tr><th>Channel</th>';
    for (var h = 0; h < freqs.length; h++) {
      html += '<th>' + escape_html(freqs[h]) + 'hz</th>';
    }
    html += '<th class="pts3-table-gap-col">_</th>';
    for (var mh = 0; mh < modeOrder.length; mh++) {
      html += "<th>" + escape_html(modeOrder[mh]) + "</th>";
    }
    html += '</tr></thead><tbody>';
    html += '<tr><td>Left</td>';
    for (var a = 0; a < freqs.length; a++) {
      html += '<td>' + escape_html(format_num(left[a])) + '</td>';
    }
    html += '<td class="pts3-table-gap-col"></td>';
    for (var ma = 0; ma < modeOrder.length; ma++) {
      html += mode_cell_for_row(modeOrder[ma], "left");
    }
    html += '</tr><tr><td>Right</td>';
    for (var b = 0; b < freqs.length; b++) {
      html += '<td>' + escape_html(format_num(right[b])) + '</td>';
    }
    html += '<td class="pts3-table-gap-col"></td>';
    for (var mb = 0; mb < modeOrder.length; mb++) {
      html += mode_cell_for_row(modeOrder[mb], "right");
    }
    html += '</tr><tr><td>Diff</td>';
    for (var c = 0; c < freqs.length; c++) {
      html += pts3_diff_td_open(diff[c]) + escape_html(format_num(diff[c])) + "</td>";
    }
    html += '<td class="pts3-table-gap-col"></td>';
    for (var mc = 0; mc < modeOrder.length; mc++) {
      html += mode_cell_for_row(modeOrder[mc], "diff");
    }
    html += '</tr></tbody></table></div>';
    html += "</div>";
    return html;
  }

  function get_mode_value(m, key) {
    if (m[key]) return m[key];
    var lower = key.toLowerCase();
    if (m[lower]) return m[lower];
    return null;
  }

  function compute_mode_hbar_axis(rows) {
    var dataMin = Infinity;
    var dataMax = -Infinity;
    for (var i = 0; i < rows.length; i++) {
      dataMin = Math.min(dataMin, rows[i].left, rows[i].right, rows[i].diff);
      dataMax = Math.max(dataMax, rows[i].left, rows[i].right, rows[i].diff);
    }
    var floorTop = MODE_HBAR.compactAxisFloor > 0 ? MODE_HBAR.compactAxisFloor : 140;
    var stepSmall = MODE_HBAR.compactTickStep > 0 ? MODE_HBAR.compactTickStep : 20;
    var stepLarge = MODE_HBAR.tickStep > 0 ? MODE_HBAR.tickStep : 250;
    if (!isFinite(dataMin) || !isFinite(dataMax)) {
      return { minVal: 0, maxVal: floorTop, tickStep: stepSmall };
    }
    var useAuto = MODE_HBAR.useAutoValueRange !== false;
    if (!useAuto) {
      var mn = MODE_HBAR.valueMin != null ? Number(MODE_HBAR.valueMin) : 0;
      var mx = MODE_HBAR.valueMax != null ? Number(MODE_HBAR.valueMax) : 3500;
      var ts = stepLarge;
      if (!isFinite(mn) || !isFinite(mx) || mn >= mx) {
        mn = 0;
        mx = 3500;
      }
      return { minVal: mn, maxVal: mx, tickStep: ts };
    }
    if (dataMax <= 300 && dataMin >= 0) {
      var maxVal = Math.max(floorTop, Math.ceil((dataMax * 1.06) / stepSmall) * stepSmall);
      return { minVal: 0, maxVal: maxVal, tickStep: stepSmall };
    }
    if (dataMin < 0) {
      var mn2 = Math.floor(dataMin / stepLarge) * stepLarge;
      var mx2 = Math.ceil(dataMax / stepLarge) * stepLarge;
      if (mn2 >= mx2) {
        mn2 -= stepLarge;
        mx2 += stepLarge;
      }
      return { minVal: mn2, maxVal: mx2, tickStep: stepLarge };
    }
    var mx3 =
      MODE_HBAR.valueMax != null ? Number(MODE_HBAR.valueMax) : Math.max(stepLarge, Math.ceil(dataMax / stepLarge) * stepLarge);
    var mn3 = MODE_HBAR.valueMin != null ? Number(MODE_HBAR.valueMin) : 0;
    if (!isFinite(mx3) || mx3 <= mn3) {
      mx3 = Math.ceil(dataMax / stepLarge) * stepLarge;
      mn3 = 0;
    }
    return { minVal: mn3, maxVal: mx3, tickStep: stepLarge };
  }

  /** Vertical grouped columns (L / R / Diff) per mode; values printed on bars when showCandleValueLabels. */
  function render_mode_chart_svg_vertical(rows, axisCfg) {
    var pw = MODE_HBAR.plotWidth > 0 ? MODE_HBAR.plotWidth : CHART.width;
    var plotH = MODE_HBAR.verticalPlotHeight > 0 ? MODE_HBAR.verticalPlotHeight : 340;
    var pad = { top: 40, right: 28, bottom: 72, left: 58 };
    var ph = pad.top + plotH + pad.bottom;
    var plotLeft = pad.left;
    var plotRight = pw - pad.right;
    var plotW = Math.max(plotRight - plotLeft, 1);
    var plotTop = pad.top;
    var plotBottom = plotTop + plotH;

    var minVal = axisCfg.minVal;
    var maxVal = axisCfg.maxVal;
    var tickStep = axisCfg.tickStep;
    if (!isFinite(minVal) || !isFinite(maxVal) || minVal >= maxVal) {
      minVal = 0;
      maxVal = MODE_HBAR.compactAxisFloor > 0 ? MODE_HBAR.compactAxisFloor : 140;
      tickStep = MODE_HBAR.compactTickStep > 0 ? MODE_HBAR.compactTickStep : 20;
    }
    var valRange = Math.max(maxVal - minVal, 1e-9);

    function yAt(val) {
      return plotBottom - ((Number(val) - minVal) / valRange) * plotH;
    }

    var axisClr = CHART.axisColor;
    var gridClr = "#e8eaed";
    var baseFs = MODE_CHART.fontSize != null ? MODE_CHART.fontSize : pts3_axis_font();
    var axisTickFs =
      MODE_HBAR.candleAxisTickFontPx != null && MODE_HBAR.candleAxisTickFontPx > 0
        ? Number(MODE_HBAR.candleAxisTickFontPx)
        : Math.max(8, baseFs - (MODE_HBAR.xTickFontShrink > 0 ? MODE_HBAR.xTickFontShrink : 5));
    var valueLabelFs =
      MODE_HBAR.candleValueFontPx != null && MODE_HBAR.candleValueFontPx > 0
        ? Number(MODE_HBAR.candleValueFontPx)
        : Math.max(7, axisTickFs - 1);
    var titleFs =
      MODE_HBAR.candleTitleFontPx != null && MODE_HBAR.candleTitleFontPx > 0
        ? Number(MODE_HBAR.candleTitleFontPx)
        : Math.max(11, axisTickFs + 2);
    var modeLabelFs =
      MODE_HBAR.candleModeLabelFontPx != null && MODE_HBAR.candleModeLabelFontPx > 0
        ? Number(MODE_HBAR.candleModeLabelFontPx)
        : axisTickFs;

    var svgFontStyle =
      "max-width:100%;height:auto;display:block;font-family:" + PTS3_SANS_FONT_STACK_CSS + ";";
    var svg =
      '<svg class="pts3-chart-svg pts3-mode-bar-chart pts3-mode-vbar-chart" viewBox="0 0 ' +
      pw +
      " " +
      ph +
      '" preserveAspectRatio="xMidYMid meet" style="' +
      svgFontStyle +
      '"><g>';

    for (var yTick = minVal; yTick <= maxVal + tickStep * 1e-6; yTick += tickStep) {
      var yy = yAt(yTick);
      svg +=
        '<line x1="' +
        plotLeft +
        '" y1="' +
        yy +
        '" x2="' +
        plotRight +
        '" y2="' +
        yy +
        '" stroke="' +
        gridClr +
        '" stroke-width="1" stroke-opacity="0.95" shape-rendering="crispEdges"/>';
      svg +=
        '<text x="' +
        (plotLeft - 8) +
        '" y="' +
        (yy + axisTickFs * 0.35) +
        '" text-anchor="end" font-size="' +
        axisTickFs +
        '" fill="' +
        axisClr +
        '">' +
        format_num(yTick) +
        "</text>";
    }

    if (minVal < 0 && maxVal > 0) {
      var y0line = yAt(0);
      if (y0line >= plotTop && y0line <= plotBottom) {
        svg +=
          '<line x1="' +
          plotLeft +
          '" y1="' +
          y0line +
          '" x2="' +
          plotRight +
          '" y2="' +
          y0line +
          '" stroke="' +
          axisClr +
          '" stroke-width="1" stroke-dasharray="4,3" opacity="0.55"/>';
      }
    }

    svg +=
      '<line x1="' +
      plotLeft +
      '" y1="' +
      plotBottom +
      '" x2="' +
      plotRight +
      '" y2="' +
      plotBottom +
      '" stroke="' +
      axisClr +
      '" stroke-width="1.25"/>';
    svg +=
      '<line x1="' +
      plotLeft +
      '" y1="' +
      plotTop +
      '" x2="' +
      plotLeft +
      '" y2="' +
      plotBottom +
      '" stroke="' +
      axisClr +
      '" stroke-width="1.25"/>';

    svg +=
      '<text x="' +
      (plotLeft + plotW / 2) +
      '" y="22" text-anchor="middle" font-size="' +
      titleFs +
      '" font-weight="600" fill="' +
      axisClr +
      '">Value</text>';

    var nModes = rows.length;
    var groupPad = 14;
    var gapBetweenGroups =
      MODE_HBAR.candleGroupGap != null && MODE_HBAR.candleGroupGap >= 0 ? Number(MODE_HBAR.candleGroupGap) : 24;
    var innerG =
      MODE_HBAR.candleInnerGap != null && MODE_HBAR.candleInnerGap >= 0
        ? Number(MODE_HBAR.candleInnerGap)
        : MODE_HBAR.innerGap != null
          ? Number(MODE_HBAR.innerGap)
          : 4;
    var contentW = Math.max(plotW - 2 * groupPad, 1);
    var totalBetweenGaps = Math.max(0, nModes - 1) * gapBetweenGroups;
    var groupSlotW = Math.max((contentW - totalBetweenGaps) / Math.max(nModes, 1), 1);
    var nBars = 3;
    var barW = Math.max(6, (groupSlotW - innerG * (nBars + 1)) / nBars);
    var wScale =
      MODE_HBAR.candleWidthScale != null && isFinite(Number(MODE_HBAR.candleWidthScale)) && Number(MODE_HBAR.candleWidthScale) > 0
        ? Number(MODE_HBAR.candleWidthScale)
        : 1;
    barW = Math.max(3, barW * wScale);
    var clusterW = nBars * barW + (nBars - 1) * innerG;
    if (clusterW > groupSlotW - 1) {
      var maxBar = Math.max(3, (groupSlotW - 1 - (nBars - 1) * innerG) / nBars);
      barW = Math.min(barW, maxBar);
      clusterW = nBars * barW + (nBars - 1) * innerG;
    }
    var usePack = MODE_HBAR.candlePackGroups !== false;
    var csp =
      MODE_HBAR.candleClusterSidePad != null && MODE_HBAR.candleClusterSidePad >= 0
        ? Number(MODE_HBAR.candleClusterSidePad)
        : 6;
    var packSlotW = clusterW + 2 * csp;
    var totalPackW = nModes * packSlotW + Math.max(0, nModes - 1) * gapBetweenGroups;
    var slotW = groupSlotW;
    var baseLeft = plotLeft + groupPad;
    if (usePack && totalPackW <= contentW) {
      slotW = packSlotW;
      var packAlign = String(MODE_HBAR.candlePackHAlign || "left").toLowerCase();
      if (packAlign === "center") {
        baseLeft = plotLeft + groupPad + (contentW - totalPackW) / 2;
      }
    }
    var cornerMax = MODE_HBAR.barCornerRadius > 0 ? MODE_HBAR.barCornerRadius : 10;
    var rx = Math.min(barW / 2, cornerMax);
    var fills = [CHART.barP1, CHART.barP2, CHART.barDiff];
    var seriesNames = ["Left", "Right", "Difference"];
    var baseVal = minVal < 0 && maxVal > 0 ? 0 : minVal;
    var yBase = yAt(baseVal);

    var regions = [];

    for (var mi = 0; mi < nModes; mi++) {
      var gLeft = baseLeft + mi * (slotW + gapBetweenGroups);
      var gx0 = gLeft + (slotW - clusterW) / 2;

      var vals = [rows[mi].left, rows[mi].right, rows[mi].diff];
      for (var k = 0; k < nBars; k++) {
        var bx = gx0 + k * (barW + innerG);
        var v = Number(vals[k]);
        var yTop = yAt(v);
        var yRectTop = Math.min(yTop, yBase);
        var hRect = Math.max(Math.abs(yBase - yTop), 0.75);

        svg +=
          '<rect x="' +
          bx +
          '" y="' +
          yRectTop +
          '" width="' +
          barW +
          '" height="' +
          hRect +
          '" rx="' +
          rx +
          '" ry="' +
          rx +
          '" fill="' +
          fills[k] +
          '" stroke="none" shape-rendering="geometricPrecision"/>';

        var tipHtml =
          "<strong>" +
          escape_html(rows[mi].label) +
          "</strong><br><span style=\"color:" +
          fills[k] +
          '">■</span> ' +
          seriesNames[k] +
          ": " +
          escape_html(format_num(v));
        regions.push({
          x0: bx,
          x1: bx + barW,
          y0: yRectTop,
          y1: yRectTop + hRect,
          html: tipHtml
        });

        if (MODE_HBAR.showCandleValueLabels !== false) {
          var lab = format_num(v);
          var ty = yRectTop - 3;
          var tx = bx + barW / 2;
          var anchor = "middle";
          var tfill = axisClr;
          if (ty < plotTop + valueLabelFs + 4) {
            ty = yRectTop + hRect + valueLabelFs + 3;
            if (ty > plotBottom + valueLabelFs + 2) {
              tx = bx + barW + 4;
              ty = yRectTop + Math.min(hRect * 0.72, valueLabelFs + 2);
              anchor = "start";
            }
          }
          if (hRect >= 4 || anchor === "start") {
            svg +=
              '<text x="' +
              tx +
              '" y="' +
              ty +
              '" text-anchor="' +
              anchor +
              '" font-size="' +
              valueLabelFs +
              '" fill="' +
              tfill +
              '" font-weight="600">' +
              escape_html(lab) +
              "</text>";
          }
        }
      }

      svg +=
        '<text x="' +
        (gLeft + slotW / 2) +
        '" y="' +
        (plotBottom + 28) +
        '" text-anchor="middle" font-size="' +
        modeLabelFs +
        '" fill="' +
        axisClr +
        '" font-weight="500">' +
        escape_html(rows[mi].label) +
        "</text>";
    }

    svg +=
      '<text x="' +
      (plotLeft + plotW / 2) +
      '" y="' +
      (ph - 8) +
      '" text-anchor="middle" font-size="' +
      titleFs +
      '" fill="' +
      axisClr +
      '">Mode</text>';

    svg += "</g></svg>";
    return { svg: svg, pack: { pw: pw, ph: ph, regions: regions } };
  }

  function render_mode_chart_svg(modeData) {
    var order = ["Mode1", "Mode2", "Mode3", "Mode0"];
    var rows = [];
    for (var i = 0; i < order.length; i++) {
      var v = get_mode_value(modeData, order[i]);
      if (v && typeof v === "object") {
        rows.push({
          label: order[i],
          left: v.p1 != null ? Number(v.p1) : 0,
          right: v.p2 != null ? Number(v.p2) : 0,
          diff: v.diff != null ? Number(v.diff) : 0
        });
      }
    }
    if (rows.length === 0) {
      return { svg: "", pack: null };
    }

    var axisCfg = compute_mode_hbar_axis(rows);
    if (MODE_HBAR.verticalCandles !== false) {
      return render_mode_chart_svg_vertical(rows, axisCfg);
    }

    var pw = MODE_HBAR.plotWidth > 0 ? MODE_HBAR.plotWidth : CHART.width;
    var rowBand = MODE_HBAR.rowBand > 0 ? MODE_HBAR.rowBand : 56;
    var innerGapCfg = MODE_HBAR.innerGap != null ? MODE_HBAR.innerGap : 4;
    var pad = { top: 28, right: 28, bottom: 52, left: 14 };
    var labelColW = MODE_HBAR.labelColW > 0 ? MODE_HBAR.labelColW : 100;
    var ph = pad.top + pad.bottom + rows.length * rowBand;

    var plotLeft = pad.left + labelColW;
    var plotRight = pw - pad.right;
    var plotW = Math.max(plotRight - plotLeft, 1);
    var plotTop = pad.top;
    var plotBottom = ph - pad.bottom;

    var minVal = axisCfg.minVal;
    var maxVal = axisCfg.maxVal;
    var tickStep = axisCfg.tickStep;
    if (!isFinite(minVal) || !isFinite(maxVal) || minVal >= maxVal) {
      minVal = 0;
      maxVal = MODE_HBAR.compactAxisFloor > 0 ? MODE_HBAR.compactAxisFloor : 140;
      tickStep = MODE_HBAR.compactTickStep > 0 ? MODE_HBAR.compactTickStep : 20;
    }
    var valRange = Math.max(maxVal - minVal, 1e-9);

    function xAt(val) {
      return plotLeft + ((Number(val) - minVal) / valRange) * plotW;
    }

    function hBarGeom(val) {
      var baseVal = minVal < 0 && maxVal > 0 ? 0 : minVal;
      var xb = xAt(baseVal);
      var xv = xAt(val);
      xb = Math.max(plotLeft, Math.min(plotRight, xb));
      xv = Math.max(plotLeft, Math.min(plotRight, xv));
      var bx = Math.min(xb, xv);
      var bw = Math.max(Math.abs(xv - xb), 0.5);
      if (bx + bw > plotRight) {
        bw = plotRight - bx;
      }
      return { x: bx, w: Math.max(bw, 0.75) };
    }

    var axisClr = CHART.axisColor;
    var gridClr = "#e8eaed";
    var fs = MODE_CHART.fontSize != null ? MODE_CHART.fontSize : pts3_axis_font();
    var fsSmall = Math.max(6, fs - 2);
    var svgFontStyle =
      "max-width:100%;height:auto;display:block;font-family:" + PTS3_SANS_FONT_STACK_CSS + ";";
    var svg =
      '<svg class="pts3-chart-svg pts3-mode-bar-chart pts3-mode-hbar-chart" viewBox="0 0 ' +
      pw +
      " " +
      ph +
      '" preserveAspectRatio="xMidYMid meet" style="' +
      svgFontStyle +
      '"><g>';

    var xfs = Math.max(7, fs - (MODE_HBAR.xTickFontShrink > 0 ? MODE_HBAR.xTickFontShrink : 5));
    for (var xVal = minVal; xVal <= maxVal + tickStep * 1e-6; xVal += tickStep) {
      var xx = xAt(xVal);
      svg +=
        '<line x1="' +
        xx +
        '" y1="' +
        plotTop +
        '" x2="' +
        xx +
        '" y2="' +
        plotBottom +
        '" stroke="' +
        gridClr +
        '" stroke-width="1" stroke-opacity="0.95" shape-rendering="crispEdges"/>';
      svg +=
        '<text x="' +
        xx +
        '" y="' +
        (ph - 14) +
        '" text-anchor="middle" font-size="' +
        xfs +
        '" fill="' +
        axisClr +
        '">' +
        format_num(xVal) +
        "</text>";
    }

    if (minVal < 0 && maxVal > 0) {
      var xz = xAt(0);
      if (xz >= plotLeft && xz <= plotRight) {
        svg +=
          '<line x1="' +
          xz +
          '" y1="' +
          plotTop +
          '" x2="' +
          xz +
          '" y2="' +
          plotBottom +
          '" stroke="' +
          axisClr +
          '" stroke-width="1" stroke-dasharray="4,3" opacity="0.5"/>';
      }
    }

    svg +=
      '<line x1="' +
      plotLeft +
      '" y1="' +
      plotBottom +
      '" x2="' +
      plotRight +
      '" y2="' +
      plotBottom +
      '" stroke="' +
      axisClr +
      '" stroke-width="1.25"/>';
    svg +=
      '<line x1="' +
      plotLeft +
      '" y1="' +
      plotTop +
      '" x2="' +
      plotLeft +
      '" y2="' +
      plotBottom +
      '" stroke="' +
      axisClr +
      '" stroke-width="1.25"/>';

    var innerGap = innerGapCfg;
    var nBars = 3;
    var barH = Math.max(8, (rowBand - innerGap * (nBars + 1)) / nBars);
    var fills = [CHART.barP1, CHART.barP2, CHART.barDiff];
    var seriesNames = ["Left", "Right", "Difference"];
    var baseValForBar = minVal < 0 && maxVal > 0 ? 0 : minVal;
    var cornerMax = MODE_HBAR.barCornerRadius > 0 ? MODE_HBAR.barCornerRadius : 10;
    var rx = Math.min(barH / 2, cornerMax);

    var regions = [];

    for (var ri = 0; ri < rows.length; ri++) {
      var yRowTop = plotTop + ri * rowBand;
      svg +=
        '<text x="' +
        (pad.left + labelColW - 10) +
        '" y="' +
        (yRowTop + rowBand / 2 + fs * 0.35) +
        '" text-anchor="end" font-size="' +
        fs +
        '" font-weight="500" fill="' +
        axisClr +
        '">' +
        escape_html(rows[ri].label) +
        "</text>";

      var vals = [rows[ri].left, rows[ri].right, rows[ri].diff];
      for (var k = 0; k < 3; k++) {
        var yb = yRowTop + innerGap + k * (barH + innerGap);
        var hg = hBarGeom(vals[k]);
        svg +=
          '<rect x="' +
          hg.x +
          '" y="' +
          yb +
          '" width="' +
          hg.w +
          '" height="' +
          barH +
          '" rx="' +
          rx +
          '" ry="' +
          rx +
          '" fill="' +
          fills[k] +
          '" stroke="none" shape-rendering="geometricPrecision"/>';

        var tipHtml =
          "<strong>" +
          escape_html(rows[ri].label) +
          "</strong><br><span style=\"color:" +
          fills[k] +
          '">■</span> ' +
          seriesNames[k] +
          ": " +
          escape_html(format_num(vals[k]));
        regions.push({
          x0: hg.x,
          x1: hg.x + hg.w,
          y0: yb,
          y1: yb + barH,
          html: tipHtml
        });

        if (MODE_HBAR.showBarValueLabels) {
          var midX = hg.x + hg.w / 2;
          var inside = hg.w > fs * 3.2;
          var tx;
          var tAnchor;
          var tFill;
          var tWeight;
          if (inside) {
            tx = midX;
            tAnchor = "middle";
            tFill = "#fff";
            tWeight = "600";
          } else if (Number(vals[k]) >= baseValForBar) {
            tx = hg.x + hg.w + 5;
            tAnchor = "start";
            tFill = axisClr;
            tWeight = "400";
          } else {
            tx = hg.x - 5;
            tAnchor = "end";
            tFill = axisClr;
            tWeight = "400";
          }
          svg +=
            '<text x="' +
            tx +
            '" y="' +
            (yb + barH * 0.72) +
            '" text-anchor="' +
            tAnchor +
            '" font-size="' +
            fsSmall +
            '" fill="' +
            tFill +
            '" font-weight="' +
            tWeight +
            '">' +
            format_num(vals[k]) +
            "</text>";
        }
      }
    }

    svg +=
      '<text x="' +
      (plotLeft + plotW / 2) +
      '" y="' +
      (ph - 2) +
      '" text-anchor="middle" font-size="' +
      Math.max(9, fs - 2) +
      '" fill="' +
      axisClr +
      '">Value</text>';
    svg += "</g></svg>";
    return { svg: svg, pack: { pw: pw, ph: ph, regions: regions } };
  }

  function render_mode(frm) {
    var m = safe_json(frm.doc.mode_values_json, null);
    if (!m || typeof m !== "object") {
      return '<div class="pts3-result-section"><h4>Mode Results</h4><p class="pts3-result-no-data">No mode data</p></div>';
    }
    var order = ["Mode1", "Mode2", "Mode3", "Mode0"];
    var html = '<div class="pts3-result-section"><h4>Mode Results</h4>';
    if (Object.keys(m).length) {
      var legendPx =
        MODE_HBAR.legendFontPx != null && MODE_HBAR.legendFontPx > 0
          ? MODE_HBAR.legendFontPx
          : MODE_CHART.fontSize != null
            ? MODE_CHART.fontSize
            : pts3_axis_font();
      html +=
        '<div class="pts3-mode-legend" style="font-size:' +
        legendPx +
        "px;font-family:" +
        PTS3_SANS_FONT_STACK_CSS +
        ';"><span style="color:' +
        CHART.barP1 +
        '">■</span> Left &nbsp; <span style="color:' +
        CHART.barP2 +
        '">■</span> Right &nbsp; <span style="color:' +
        CHART.barDiff +
        '">■</span> Difference</div>';
      var chartOut = render_mode_chart_svg(m);
      var packEnc = "";
      if (chartOut.pack && chartOut.pack.regions && chartOut.pack.regions.length) {
        try {
          packEnc = encodeURIComponent(JSON.stringify(chartOut.pack));
        } catch (ePack) {
          packEnc = "";
        }
      }
      html += '<div class="pts3-mode-layout">';
      html += '<div class="pts3-mode-chart pts3-mode-chart-only"><div class="pts3-chart-wrap">';
      if (packEnc && chartOut.svg) {
        html +=
          '<div class="pts3-mode-chart-container" data-mode-regions="' +
          packEnc +
          '" style="position:relative;display:block;">' +
          '<div class="pts3-mode-tooltip pts3-sweep-tooltip"></div>' +
          chartOut.svg +
          "</div>";
      } else {
        html += chartOut.svg || "";
      }
      html += "</div></div></div>";
    }
    html += "</div>";
    return html;
  }

  function render_lrd_summary(frm) {
    var t = safe_json(frm.doc.left_right_diff_summary_json, null);
    if (!t || typeof t !== "object") {
      return '<div class="pts3-result-section"><h4>Left / Right / Diff Summary</h4><p class="pts3-result-no-data">No data</p></div>';
    }
    var meta = t.metadata || {};
    var left = t.left || {};
    var right = t.right || {};
    var diff = t.diff || {};
    var keys = Object.keys(left).concat(Object.keys(right)).concat(Object.keys(diff));
    keys = keys.filter(function (k, i, a) { return a.indexOf(k) === i; }).sort();
    var html = '<div class="pts3-result-section"><h4>Left / Right / Diff Summary</h4>';
    if (Object.keys(meta).length) {
      html += "<p><strong>Metadata:</strong> " + escape_html(JSON.stringify(meta)) + "</p>";
    }
    html += "<table class=\"pts3-result-table\"><thead><tr><th>Key</th><th>Left</th><th>Right</th><th>Diff</th></tr></thead><tbody>";
    for (var i = 0; i < keys.length; i++) {
      var k = keys[i];
      html +=
        "<tr><td>" +
        escape_html(k) +
        "</td><td>" +
        escape_html(left[k] != null ? left[k] : "") +
        "</td><td>" +
        escape_html(right[k] != null ? right[k] : "") +
        "</td>" +
        pts3_diff_td_open(diff[k]) +
        escape_html(diff[k] != null ? diff[k] : "") +
        "</td></tr>";
    }
    html += "</tbody></table></div>";
    return html;
  }

  function render_artifacts(frm) {
    var ap = frm.doc.artifact_paths || "";
    var html = '<div class="pts3-result-section"><h4>Artifacts</h4>';
    var obj = null;
    if (typeof ap === "string" && ap.trim()) {
      try {
        obj = JSON.parse(ap);
      } catch (e) {
        obj = null;
      }
    }
    if (obj && typeof obj === "object") {
      var pc = obj.pc_name || "";
      var excel = obj.excel_path || "";
      var log = obj.log_path || "";
      var plot = obj.plot_path || "";
      html += "<div class=\"pts3-result-artifact\"><strong>PC:</strong> " + escape_html(pc || "(not set)") + "</div>";
      html += "<div class=\"pts3-result-artifact\"><strong>Excel:</strong> " + escape_html(excel || "-") + "</div>";
      html += "<div class=\"pts3-result-artifact\"><strong>Log:</strong> " + escape_html(log || "-") + "</div>";
      html += "<div class=\"pts3-result-artifact\"><strong>Plot:</strong> " + escape_html(plot || "-") + "</div>";
    } else if (ap && typeof ap === "string") {
      html += "<div class=\"pts3-result-artifact\"><strong>Legacy path:</strong> " + escape_html(ap) + "</div>";
    } else {
      html += "<p class=\"pts3-result-no-data\">No artifact paths</p>";
    }
    html += "</div>";
    return html;
  }

  function load_html2canvas(done) {
    if (typeof window.html2canvas === "function") {
      done();
      return;
    }
    if (window.__pts3_h2c_loading) {
      window.__pts3_h2c_queue = window.__pts3_h2c_queue || [];
      window.__pts3_h2c_queue.push(done);
      return;
    }
    window.__pts3_h2c_loading = true;
    var sc = document.createElement("script");
    sc.src = HTML2CANVAS_CDN;
    sc.crossOrigin = "anonymous";
    sc.onload = function () {
      window.__pts3_h2c_loading = false;
      done();
      var q = window.__pts3_h2c_queue || [];
      window.__pts3_h2c_queue = [];
      for (var qi = 0; qi < q.length; qi++) {
        q[qi]();
      }
    };
    sc.onerror = function () {
      window.__pts3_h2c_loading = false;
      frappe.msgprint(__("Could not load html2canvas (CDN blocked or offline)."));
    };
    document.head.appendChild(sc);
  }

  function bind_inspection_download(frm, $wrapper) {
    $wrapper.find(".pts3-download-inspection-png").off("click.pts3cap");
    $wrapper.find(".pts3-download-inspection-png").on("click.pts3cap", function () {
      var root = $wrapper.find(".pts3-inspection-capture-body")[0];
      if (!root) {
        frappe.msgprint(__("Nothing to capture."));
        return;
      }
      load_html2canvas(function () {
        frappe.show_alert({ message: __("Rendering PNG…"), indicator: "blue" });
        var bg = "#ffffff";
        try {
          var b = getComputedStyle(document.body);
          if (b && b.backgroundColor && b.backgroundColor !== "rgba(0, 0, 0, 0)" && b.backgroundColor !== "transparent") {
            bg = b.backgroundColor;
          }
        } catch (e0) {}
        window
          .html2canvas(root, {
            scale: INSPECTION_PNG_SCALE,
            useCORS: true,
            allowTaint: true,
            logging: false,
            backgroundColor: bg,
            ignoreElements: function (el) {
              return el.classList && el.classList.contains("pts3-inspection-toolbar");
            },
          })
          .then(function (canvas) {
            canvas.toBlob(
              function (blob) {
                if (!blob) {
                  frappe.msgprint(__("PNG export failed."));
                  return;
                }
                var name = (frm.doc.name || "PTS3_Result").replace(/[^\w.-]+/g, "_");
                var a = document.createElement("a");
                a.href = URL.createObjectURL(blob);
                a.download = name + "_inspection.png";
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                URL.revokeObjectURL(a.href);
                frappe.show_alert({ message: __("Download started"), indicator: "green" });
              },
              "image/png",
              0.98
            );
          })
          .catch(function (err) {
            frappe.msgprint(__("Capture error: ") + (err && err.message ? err.message : String(err)));
          });
      });
    });
  }

  function render_inspection(frm) {
    if (!frm.doc.name) return "";
    var inner =
      '<div class="pts3-summary-mode-row">' +
      render_summary(frm) +
      render_mode(frm) +
      "</div>" +
      render_step_sweep(frm);
    if (SHOW_LEFT_RIGHT_DIFF_SUMMARY_SECTION) {
      inner += render_lrd_summary(frm);
    }
    inner += render_artifacts(frm);
    return (
      '<div class="pts3-inspection-capture-root" style="width:100%;max-width:100%;box-sizing:border-box;margin:0;display:block;">' +
      '<table role="presentation" style="width:100%;max-width:100%;border-collapse:collapse;margin:0;padding:0;border:none;"><tr><td style="padding:0;border:none;vertical-align:top;width:100%;">' +
      '<div class="pts3-inspection-toolbar">' +
      '<button type="button" class="btn btn-default btn-sm pts3-download-inspection-png">' +
      __("Download inspection as PNG") +
      "</button>" +
      '<span class="text-muted small">' +
      __("Uses html2canvas from CDN; scale ") +
      String(INSPECTION_PNG_SCALE) +
      "×</span></div>" +
      '<div class="pts3-inspection-capture-body" style="width:100%;max-width:100%;box-sizing:border-box;">' +
      inner +
      "</div></td></tr></table></div>"
    );
  }

  function setup_sweep_hover() {
    $(document).off("mousemove.pts3sweep mouseleave.pts3sweep");
    $(document).on("mousemove.pts3sweep", ".pts3-sweep-chart-container", function (e) {
      var $c = $(this);
      var dataStr = $c.attr("data-sweep");
      if (!dataStr) return;
      var data;
      try {
        data = JSON.parse(dataStr);
      } catch (err) {
        return;
      }
      var coords = data.coords;
      var freqs = data.freqs || [];
      var left = data.left || [];
      var right = data.right || [];
      var diff = data.diff || [];
      if (!coords || !freqs.length) return;
      var svg = $c.find("svg")[0];
      if (!svg) return;
      var rect = svg.getBoundingClientRect();
      var vx = ((e.clientX - rect.left) / rect.width) * coords.pw;
      var vy = ((e.clientY - rect.top) / rect.height) * coords.ph;
      if (vx < coords.gx || vx > coords.gx + coords.gw || vy < coords.gy || vy > coords.gy + coords.gh) {
        $c.find(".pts3-sweep-tooltip").removeClass("visible");
        return;
      }
      var freq = coords.freqMin + ((vx - coords.gx) / coords.gw) * coords.freqRange;
      var idx = Math.round(((vx - coords.gx) / coords.gw) * (freqs.length - 1));
      idx = Math.max(0, Math.min(idx, freqs.length - 1));
      var f = Number(freqs[idx]);
      var l = left[idx] != null ? format_num(left[idx]) : "-";
      var r = right[idx] != null ? format_num(right[idx]) : "-";
      var d = diff[idx] != null ? format_num(diff[idx]) : "-";
      var $tip = $c.find(".pts3-sweep-tooltip");
      var cRect = $c[0].getBoundingClientRect();
      $tip.html("<strong>" + f + " Hz</strong><br>Left: " + l + " &nbsp; Right: " + r + " &nbsp; Diff: " + d);
      $tip.css({ left: (e.clientX - cRect.left + 12) + "px", top: (e.clientY - cRect.top + 12) + "px" });
      $tip.addClass("visible");
    });
    $(document).on("mouseleave.pts3sweep", ".pts3-sweep-chart-container", function () {
      $(this).find(".pts3-sweep-tooltip").removeClass("visible");
    });
  }

  function setup_mode_hover() {
    $(document).off("mousemove.pts3mode mouseleave.pts3mode");
    $(document).on("mousemove.pts3mode", ".pts3-mode-chart-container", function (e) {
      var $c = $(this);
      var raw = $c.attr("data-mode-regions");
      if (!raw) return;
      var pack;
      try {
        pack = JSON.parse(decodeURIComponent(raw));
      } catch (err) {
        return;
      }
      if (!pack || !pack.regions || !pack.regions.length) return;
      var svg = $c.find("svg")[0];
      if (!svg) return;
      var srect = svg.getBoundingClientRect();
      if (!srect.width || !srect.height) return;
      var vx = ((e.clientX - srect.left) / srect.width) * pack.pw;
      var vy = ((e.clientY - srect.top) / srect.height) * pack.ph;
      var hit = null;
      for (var i = 0; i < pack.regions.length; i++) {
        var r = pack.regions[i];
        if (vx >= r.x0 && vx <= r.x1 && vy >= r.y0 && vy <= r.y1) {
          hit = r;
          break;
        }
      }
      var $tip = $c.find(".pts3-mode-tooltip");
      if (!hit) {
        $tip.removeClass("visible");
        return;
      }
      $tip.html(hit.html);
      var cRect = $c[0].getBoundingClientRect();
      $tip.css({ left: e.clientX - cRect.left + 12 + "px", top: e.clientY - cRect.top + 12 + "px" });
      $tip.addClass("visible");
    });
    $(document).on("mouseleave.pts3mode", ".pts3-mode-chart-container", function () {
      $(this).find(".pts3-mode-tooltip").removeClass("visible");
    });
  }

  /** Same as Desk → user menu → Toggle Full Width (ON). Persists in localStorage like the built-in toggle. */
  function pts3_ensure_desk_full_width() {
    if (!PTS3_ENABLE_DESK_FULL_WIDTH_ON_LOAD) return;
    try {
      if (typeof localStorage !== "undefined") {
        localStorage.setItem("container_fullwidth", "true");
      }
      if (typeof frappe !== "undefined" && frappe.ui && frappe.ui.toolbar && typeof frappe.ui.toolbar.set_fullwidth_if_enabled === "function") {
        frappe.ui.toolbar.set_fullwidth_if_enabled();
      } else if (typeof $ !== "undefined" && $(document.body).length) {
        $(document.body).addClass("full-width");
      }
      if (typeof $ !== "undefined") {
        $(document.body).trigger("toggleFullWidth");
      }
    } catch (e) {}
  }

  frappe.ui.form.on("PTS3 Result", {
    onload: function () {
      setTimeout(pts3_ensure_desk_full_width, 0);
    },
    refresh: function (frm) {
      pts3_ensure_desk_full_width();
      pts3Dbg(
        "PTS3 Result refresh",
        frm.doc.name,
        "run_id=" + (frm.doc.run_id || ""),
        "op=" + (frm.doc.operation || ""),
        "final_graph_json len=" + String(frm.doc.final_graph_json || "").length,
        "left_right_diff_summary_json len=" + String(frm.doc.left_right_diff_summary_json || "").length,
        "mode_values_json len=" + String(frm.doc.mode_values_json || "").length
      );
      var field = frm.get_field("result_inspection");
      if (field && field.$wrapper) {
        field.$wrapper.html(render_inspection(frm));
        setup_sweep_hover();
        setup_mode_hover();
        bind_inspection_download(frm, field.$wrapper);
      }
    }
  });
})();
